<a class="text-link" href="<?= e(url('admin/list',['module'=>$module])) ?>">← Back to <?= e(strtolower($m['title'])) ?></a><form action="<?= e(url('admin/save')) ?>" method="post" enctype="multipart/form-data" class="panel mt-4"><?= csrf() ?><input type="hidden" name="module" value="<?= e($module) ?>"><input type="hidden" name="id" value="<?= $id ?>"><div class="form-grid"><?php foreach($m['fields'] as $field=>$type): $value=$row[$field]??($type==='bool'?1:($type==='number'||$type==='money'?0:'')); ?><label class="<?= in_array($type,['textarea','image'])?'full-width':'' ?>"><?= e(ucwords(str_replace('_',' ',$field))) ?><?= $type==='money'?' (INR)':'' ?><?php if($type==='textarea'): ?><textarea class="form-control" name="<?= e($field) ?>" rows="4"><?= e($value) ?></textarea><?php elseif($type==='bool'): ?><input class="form-check-input ms-2" type="checkbox" name="<?= e($field) ?>" value="1" <?= $value?'checked':'' ?>><?php elseif($type==='image'): ?><?php if($value): ?><img class="admin-image-preview" src="<?= e(asset($value)) ?>" alt="Current image"><?php endif ?><input class="form-control image-input" type="file" name="<?= e($field) ?>" accept="image/jpeg,image/png,image/webp"><small class="muted">JPG, PNG or WebP, maximum 5 MB.</small><?php elseif(in_array($type,['category','product','optional_category','optional_product'])): $optional=str_starts_with($type,'optional_');$table=str_contains($type,'category')?'categories':'products'; ?><select class="form-select" name="<?= e($field) ?>" <?= !$optional?'required':'' ?>><?php if($optional): ?><option value="">All / not restricted</option><?php endif ?><?php foreach($editorOptions[$table] as $option): ?><option value="<?= $option['id'] ?>" <?= $option['id']==$value?'selected':'' ?>>#<?= $option['id'] ?> · <?= e($option['name']) ?></option><?php endforeach ?></select><?php elseif(str_starts_with($type,'select:')): ?><select class="form-select" name="<?= e($field) ?>"><?php foreach(explode(',',substr($type,7)) as $option): ?><option <?= $option===$value?'selected':'' ?> value="<?= e($option) ?>"><?= e(ucfirst($option)) ?></option><?php endforeach ?></select><?php else: ?><input class="form-control" name="<?= e($field) ?>" type="<?= $type==='datetime'?'datetime-local':($type==='money'?'number':$type) ?>" <?= $type==='money'?'step="0.01" min="0"':($type==='number'?'min="0"':'') ?> value="<?= $type==='password'?'':e($type==='money'?number_format((int)$value/100,2,'.',''):($type==='datetime'&&$value?date('Y-m-d\TH:i',strtotime($value)):$value)) ?>" <?= in_array($field,['name','slug','sku','label','code'])?'required':'' ?>><?php endif ?><?php if($field==='value' && $module==='coupons'): ?><small class="muted">For percent: 10 means 10%. For fixed: enter paise (10000 = ₹100).</small><?php endif ?><?php if($field==='password' && $id): ?><small class="muted">Leave blank to keep the existing password.</small><?php endif ?></label><?php endforeach ?></div><?php if($module==='bundles'): $selected=$selectedProducts; ?><h3 class="mt-4">Eligible products</h3><div class="checkbox-grid"><?php foreach($editorOptions['products'] as $p): ?><label><input type="checkbox" name="eligible_products[]" value="<?= $p['id'] ?>" <?= in_array($p['id'],$selected)?'checked':'' ?>> <?= e($p['name']) ?></label><?php endforeach ?></div><p class="muted small">A nonzero fixed price overrides the percentage discount for each qualifying selection.</p><?php endif ?><button class="btn btn-primary mt-4">Save changes</button></form><?php if($id && isset($m['fields']['active']) && $module!=='admins'): ?><form action="<?= e(url('admin/archive')) ?>" method="post" class="mt-3" data-confirm="Archive this record? You can reactivate it by editing it."><?= csrf() ?><input type="hidden" name="module" value="<?= e($module) ?>"><input type="hidden" name="id" value="<?= $id ?>"><button class="btn btn-outline-danger">Archive record</button></form><?php endif ?>
